unsafe fn xmlHashUpdateInternal(
    mut hash: xmlHashTablePtr,
    mut key: *const xmlChar,
    mut key2: *const xmlChar,
    mut key3: *const xmlChar,
    mut payload: *mut c_void,
    mut dealloc: xmlHashDeallocator,
    mut update: c_int,
) -> c_int {
    if hash.is_null() || key.is_null() {
        return -(1 as c_int);
    }

    let mut copy: *mut xmlChar = ::core::ptr::null_mut();
    let mut copy2: *mut xmlChar = ::core::ptr::null_mut();
    let mut copy3: *mut xmlChar = ::core::ptr::null_mut();
    let mut entry: *mut xmlHashEntry = ::core::ptr::null_mut();
    let mut lengths: [size_t; 3] = [0; 3];
    let mut found: c_int = 0;

    let hashValue = xmlHashValue(
        (*hash).randomSeed,
        key,
        key2,
        key3,
        &raw mut lengths as *mut size_t,
    );

    if (*hash).size > 0 as c_uint {
        entry = xmlHashFindEntry(
            hash as *const xmlHashTable,
            key,
            key2,
            key3,
            hashValue,
            &raw mut found,
        );
    }

    if found != 0 {
        if update != 0 {
            if let Some(dealloc_fn) = dealloc {
                dealloc_fn((*entry).payload, (*entry).key);
            }
            (*entry).payload = payload;
            return 0 as c_int;
        }
        return -(1 as c_int);
    }

    let hash_ref = &mut *hash;

    if hash_ref.nbElems.wrapping_add(1 as c_uint)
        > hash_ref
            .size
            .wrapping_div(MAX_FILL_DENOM as c_uint)
            .wrapping_mul(MAX_FILL_NUM as c_uint)
    {
        let newSize: c_uint = if hash_ref.size == 0 as c_uint {
            MIN_HASH_SIZE as c_uint
        } else {
            if hash_ref.size >= MAX_HASH_SIZE {
                return -(1 as c_int);
            }
            hash_ref.size.wrapping_mul(2 as c_uint)
        };

        if xmlHashGrow(hash, newSize) != 0 as c_int {
            return -(1 as c_int);
        }

        let mask = (*hash).size.wrapping_sub(1 as c_uint);
        let mut displ = 0 as c_uint;
        let mut pos = hashValue & mask;
        entry = (*hash).table.add(pos as usize);
        if (*entry).hashValue != 0 as c_uint {
            loop {
                displ = displ.wrapping_add(1);
                pos = pos.wrapping_add(1);
                entry = entry.add(1);
                if pos & mask == 0 as c_uint {
                    entry = (*hash).table;
                }
                if !((*entry).hashValue != 0 as c_uint
                    && pos.wrapping_sub((*entry).hashValue) & mask >= displ)
                {
                    break;
                }
            }
        }
    }

    let dict = (*hash).dict;
    if !dict.is_null() {
        if xmlDictOwns(dict, key) != 0 {
            copy = key as *mut xmlChar;
        } else {
            copy = xmlDictLookup(dict, key, -(1 as c_int)) as *mut xmlChar;
            if copy.is_null() {
                return -(1 as c_int);
            }
        }

        if key2.is_null() || xmlDictOwns(dict, key2) != 0 {
            copy2 = key2 as *mut xmlChar;
        } else {
            copy2 = xmlDictLookup(dict, key2, -(1 as c_int)) as *mut xmlChar;
            if copy2.is_null() {
                return -(1 as c_int);
            }
        }

        if key3.is_null() || xmlDictOwns(dict, key3) != 0 {
            copy3 = key3 as *mut xmlChar;
        } else {
            copy3 = xmlDictLookup(dict, key3, -(1 as c_int)) as *mut xmlChar;
            if copy3.is_null() {
                return -(1 as c_int);
            }
        }
    } else {
        let malloc_fn = xmlMalloc.expect("non-null function pointer");
        let free_fn = xmlFree.expect("non-null function pointer");

        let len0 = lengths[0].wrapping_add(1 as size_t);
        copy = malloc_fn(len0) as *mut xmlChar;
        if copy.is_null() {
            return -(1 as c_int);
        }
        // SAFETY: copy points to a valid allocation of len0 bytes, key points to at least len0 readable bytes including the NUL terminator as computed by xmlHashValue, and the regions do not overlap.
        unsafe {
            memcpy(copy as *mut c_void, key as *const c_void, len0);
        }

        if !key2.is_null() {
            let len1 = lengths[1].wrapping_add(1 as size_t);
            copy2 = malloc_fn(len1) as *mut xmlChar;
            if copy2.is_null() {
                free_fn(copy as *mut c_void);
                return -(1 as c_int);
            }
            // SAFETY: copy2 points to a valid allocation of len1 bytes, key2 points to at least len1 readable bytes including the NUL terminator as computed by xmlHashValue, and the regions do not overlap.
            unsafe {
                memcpy(copy2 as *mut c_void, key2 as *const c_void, len1);
            }
        }

        if !key3.is_null() {
            let len2 = lengths[2].wrapping_add(1 as size_t);
            copy3 = malloc_fn(len2) as *mut xmlChar;
            if copy3.is_null() {
                free_fn(copy as *mut c_void);
                free_fn(copy2 as *mut c_void);
                return -(1 as c_int);
            }
            // SAFETY: copy3 points to a valid allocation of len2 bytes, key3 points to at least len2 readable bytes including the NUL terminator as computed by xmlHashValue, and the regions do not overlap.
            unsafe {
                memcpy(copy3 as *mut c_void, key3 as *const c_void, len2);
            }
        }
    }

    if (*entry).hashValue != 0 as c_uint {
        let table = (*hash).table;
        let end = table.add((*hash).size as usize);
        let mut cur = entry;

        loop {
            cur = cur.add(1);
            if cur >= end {
                cur = table;
            }
            if (*cur).hashValue == 0 as c_uint {
                break;
            }
        }

        if cur < entry {
            // SAFETY: source and destination are within the same allocated table buffer and may overlap; byte count covers the prefix [table, cur).
            unsafe {
                memmove(
                    table.add(1) as *mut c_void,
                    table as *const c_void,
                    (cur as *mut c_char).offset_from(table as *mut c_char) as c_long as size_t,
                );
            }
            cur = end.sub(1);
            *table = *cur;
        }

        // SAFETY: source and destination are within the same allocated table buffer and may overlap; byte count covers the occupied range [entry, cur).
        unsafe {
            memmove(
                entry.add(1) as *mut c_void,
                entry as *const c_void,
                (cur as *mut c_char).offset_from(entry as *mut c_char) as c_long as size_t,
            );
        }
    }

    (*entry).key = copy;
    (*entry).key2 = copy2;
    (*entry).key3 = copy3;
    (*entry).payload = payload;
    (*entry).hashValue = hashValue | MAX_HASH_SIZE;
    (*hash).nbElems = (*hash).nbElems.wrapping_add(1);
    0 as c_int
}

